INSERT INTO regle_constante (id, valeur, unite, nature, texte, page_id, origine, source_ref, remarque) VALUES ('ceinture.exemplaires_par_emplacement', 3, 'exemplaires', 'texte', 'Les objets sont dans la ceinture ne peuvent pas dépasser le nombre de 3 (impossible de cumuler les objets à l''infini)', 'guide/fiche-accessoires-et-ceinture', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Ceinture', 'Décision R89 : au plus 3 exemplaires du même objet par emplacement de la ceinture (4 avec un don qui l''écrit) ; le bâton magique compte 1 ; un carquois ou un sac compte ses projectiles, jusqu''à sa contenance.');
