INSERT INTO regle_constante (id, valeur, unite, nature, texte, page_id, origine, source_ref, remarque) VALUES ('inventaire.colonnes_de_depart', 2, 'colonnes', 'texte', 'Par défaut, votre personnage commence avec un sac à dos normal, ce qui correspond à deux colonnes complètes d’inventaire mais il existe d’autres sacs à dos.', 'guide/fiche-inventaire-sac-a-dos', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Inventaire/Sac à dos', 'Décision R88 : la Force donne la place, sans sac à choisir ; à Force 1, les deux colonnes du sac normal (24 emplacements).');
