INSERT INTO regle_constante (id, valeur, unite, nature, texte, page_id, origine, source_ref, remarque) VALUES ('inventaire.force_tout_l_inventaire', 5, 'points', 'texte', 'Ultra sac à dos, permet d’avoir tout l’inventaire |Demande 5 de Force.', 'guide/fiche-inventaire-sac-a-dos', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Inventaire/Sac à dos', 'Décision R88 : à partir de Force 5, tout l''inventaire (inventaire.colonnes_max colonnes, 48 emplacements).');
